insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('como-cambia-la-actividad-fisica-con-la-edad','salud',array['sociedad']::text[],'¿Cómo cambia la actividad física con la edad?','Compara cómo se mueven las personas en distintas etapas de la vida y descubre qué cambia en el tiempo, el lugar, la motivación y los obstáculos.','Análisis','~15 h',15,array['Actividad física','Ciclo de vida']::text[],array['investigar','otro-sector']::text[],'publicos',NULL,'medicina enfermeria psicologia sociologia estadistica educacion trabajo social nutricion analisis comparativo. lectura de datos publicos. diseno de graficos. sensibilidad a distintos contextos. hoja de calculo y graficos. portales de estadisticas publicas. documento o presentacion.',$f18sld${"id": "como-cambia-la-actividad-fisica-con-la-edad", "area": "salud", "areas2": ["sociedad"], "titulo": "¿Cómo cambia la actividad física con la edad?", "resumen": "Compara cómo se mueven las personas en distintas etapas de la vida y descubre qué cambia en el tiempo, el lugar, la motivación y los obstáculos.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Actividad física", "Ciclo de vida"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Medicina", "Enfermería", "Psicología", "Sociología", "Estadística", "Educación", "Trabajo Social", "Nutrición"], "problema": ["Una persona de quince años, una de treinta, una de cincuenta y una de setenta no se mueven por las mismas razones ni con las mismas posibilidades. Cambian el tiempo libre, la energía, las responsabilidades y lo que se considera «ejercicio».", "Los mensajes sobre actividad física suelen dirigirse a un solo perfil, el de la persona joven y con tiempo, y dejan fuera a quienes más lo necesitan."], "desarrollar": ["Reúne datos públicos y estudios sobre actividad física en cuatro o cinco etapas de la vida. Para cada una, resume cuánto se mueve la gente, de qué manera y qué obstáculos tiene.", "Con eso construye un cuadro comparativo y una propuesta de qué ofrecería una comunidad para cada grupo. El resultado puede ser un informe visual con gráficos y una guía de ideas de actividades."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo cambian estos patrones entre zonas urbanas y rurales o entre contextos distintos."}, {"titulo": "Un paso más", "aporta": "diseña un programa de actividades para dos etapas de la vida a la vez, como abuelos y nietos."}, {"titulo": "Otro formato", "aporta": "transforma el cuadro en un mapa o infografía de fácil lectura."}], "objetivos": ["Reunir datos sobre actividad física en distintas edades.", "Comparar etapas de la vida.", "Identificar obstáculos propios de cada etapa.", "Proponer ideas de actividades adecuadas."], "habilidades": ["Análisis comparativo.", "Lectura de datos públicos.", "Diseño de gráficos.", "Sensibilidad a distintos contextos."], "herramientas": ["Hoja de cálculo y gráficos.", "Portales de estadísticas públicas.", "Documento o presentación."], "lineamientos": ["Trabaja con datos y estudios públicos; no recomiendes ejercicios ni cantidades de actividad a personas concretas.", "Evita estereotipos: no todas las personas de una edad son iguales. Indica los límites de los datos que uses."], "otroSector": "El mismo análisis sirve para el uso de internet, del transporte, del ocio o del ahorro según la etapa de la vida."}$f18sld$::jsonb,18),
('como-moverse-mas-una-estrategia-contra-el-sedentarismo','salud',array['ciudades']::text[],'Cómo moverse más: una estrategia contra el sedentarismo','Diseña una estrategia sencilla para que un grupo pase menos tiempo sentado, aprovechando su lugar de estudio o de trabajo.','Plan','~20 h',20,array['Actividad física','Prevención','Entorno']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social medicina enfermeria administracion comunicaciones arquitectura ingenieria civil educacion observacion de espacios. diseno de estrategias. comunicacion persuasiva. evaluacion con indicadores sencillos. hoja de calculo. croquis o planos sencillos. documento o presentacion.',$f19sld${"id": "como-moverse-mas-una-estrategia-contra-el-sedentarismo", "area": "salud", "areas2": ["ciudades"], "titulo": "Cómo moverse más: una estrategia contra el sedentarismo", "resumen": "Diseña una estrategia sencilla para que un grupo pase menos tiempo sentado, aprovechando su lugar de estudio o de trabajo.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Actividad física", "Prevención", "Entorno"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Trabajo Social", "Medicina", "Enfermería", "Administración", "Comunicaciones", "Arquitectura", "Ingeniería Civil", "Educación"], "problema": ["Muchas personas pasan la mayor parte del día sentadas: en clases, frente a una computadora, en el transporte. No es una decisión: el entorno está hecho así.", "Las campañas contra el sedentarismo suelen decir «muévete más» sin cambiar el espacio ni los horarios, y por eso sirven poco. Pequeños cambios en cómo se organiza un lugar pueden hacer más que un afiche."], "desarrollar": ["Elige un lugar, como un salón, una oficina o una biblioteca, y observa dónde y cuánto tiempo pasa sentada la gente. Diseña una estrategia de tres o cuatro cambios pequeños: pausas, reuniones de pie, caminos a recorrer, recordatorios y otros.", "Define cómo se podría comprobar que funciona. El resultado puede ser un plan con acciones, responsables y materiales, que pueda proponerse a una organización real."], "ampliaciones": [{"titulo": "Una prueba", "aporta": "aplica una de las acciones en un grupo pequeño durante una semana y mide qué cambió."}, {"titulo": "Otra mirada", "aporta": "estudia cómo el diseño del espacio, como escaleras visibles o mesas altas, invita o no a moverse."}, {"titulo": "Un paso más", "aporta": "piensa cómo adaptar la estrategia para personas con movilidad reducida."}], "objetivos": ["Observar cómo se usa el tiempo sentado en un lugar.", "Diseñar acciones pequeñas y realistas.", "Plantear cómo medir el resultado.", "Presentar la estrategia a una organización."], "habilidades": ["Observación de espacios.", "Diseño de estrategias.", "Comunicación persuasiva.", "Evaluación con indicadores sencillos."], "herramientas": ["Hoja de cálculo.", "Croquis o planos sencillos.", "Documento o presentación."], "lineamientos": ["Pide permiso antes de observar o probar algo en un lugar y no fotografíes a las personas. Las acciones deben ser seguras para cualquiera, no ejercicios exigentes.", "Considera a quienes tienen limitaciones de movilidad: ninguna acción debe excluirlos ni señalarlos."], "otroSector": "La misma estrategia sirve para reducir el uso de papel, ahorrar energía o mejorar la convivencia en un espacio."}$f19sld$::jsonb,19),
('cuanta-agua-tomas-de-verdad','salud',array['educacion']::text[],'¿Cuánta agua tomas de verdad?','Registra durante unos días cuánta agua tomas y descubre qué influye en que olvides tomarla, y qué ayuda a recordarlo sin esfuerzo.','Análisis','~8 h',8,array['Hidratación','Hábitos','Registro']::text[],array['investigar','resolver']::text[],'propios',NULL,'nutricion medicina enfermeria psicologia educacion estadistica ingenieria industrial ingenieria ambiental registro y analisis de habitos. observacion personal. diseno de recordatorios. comunicacion clara. hoja de calculo o cuaderno. botella o recipiente con medidas. herramientas para crear carteles.',$f20sld${"id": "cuanta-agua-tomas-de-verdad", "area": "salud", "areas2": ["educacion"], "titulo": "¿Cuánta agua tomas de verdad?", "resumen": "Registra durante unos días cuánta agua tomas y descubre qué influye en que olvides tomarla, y qué ayuda a recordarlo sin esfuerzo.", "tipo": "Análisis", "tiempo": "~8 h", "horas": 8, "etiquetas": ["Hidratación", "Hábitos", "Registro"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Nutrición", "Medicina", "Enfermería", "Psicología", "Educación", "Estadística", "Ingeniería Industrial", "Ingeniería Ambiental"], "problema": ["Sobre la hidratación circulan muchas frases, como «toma ocho vasos al día», que casi nadie comprueba. Cada persona necesita distinto, y a menudo ni siquiera sabe cuánto toma realmente.", "Entre clases, trabajo y distracciones, se olvida beber. Cuando lo notamos, ya estamos cansados o con dolor de cabeza, y creemos que es por otra cosa."], "desarrollar": ["Registra por cinco o siete días cuántas veces tomas agua y en qué momentos, sin cambiar tus hábitos. Anota qué te hizo olvidar o recordar: estar en clase, el calor, tener la botella a la vista.", "Con los datos, identifica tus momentos de mayor olvido y prueba una idea sencilla para recordarlo. El resultado puede ser un cuadro de tus hábitos y una pequeña guía de ideas para hidratarse mejor sin obsesionarse con la cantidad."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta las ideas a niños, deportistas o adultos mayores, que suelen sentir menos sed."}, {"titulo": "Otra mirada", "aporta": "investiga qué factores del clima, de la ropa o del trabajo cambian lo que se necesita."}, {"titulo": "Otro formato", "aporta": "diseña un recordatorio visual, como una botella marcada o un cartel, y pruébalo."}], "objetivos": ["Registrar los hábitos de hidratación durante varios días.", "Identificar cuándo y por qué se olvida beber.", "Probar una idea sencilla de recordatorio.", "Comunicar los hallazgos."], "habilidades": ["Registro y análisis de hábitos.", "Observación personal.", "Diseño de recordatorios.", "Comunicación clara."], "herramientas": ["Hoja de cálculo o cuaderno.", "Botella o recipiente con medidas.", "Herramientas para crear carteles."], "lineamientos": ["Es un ejercicio de observación, no una recomendación médica: no sugieras cantidades como obligatorias. Personas con condiciones de salud deben consultar a un profesional.", "Trabaja con tus propios datos o los de quienes acepten participar, sin identificarlos."], "otroSector": "El mismo método sirve para observar el uso de agua en casa, el consumo de energía o el tiempo en pantallas."}$f20sld$::jsonb,20),
('un-registro-de-bienestar-que-si-quieras-llenar','salud',array['tecnologia']::text[],'Un registro de bienestar que sí quieras llenar','Diseña una herramienta sencilla para anotar sueño, ánimo, movimiento o comidas, y prueba qué la hace fácil de usar días tras día.','Prototipo','~15 h',15,array['Registro de hábitos','Experiencia de usuario']::text[],array['crear','resolver']::text[],'propios',NULL,'ingenieria de sistemas ingenieria de software psicologia diseno grafico medicina educacion estadistica comunicaciones diseno centrado en las personas. prototipado. observacion de habitos. presentacion de datos. hoja de calculo o herramienta de maquetas. papel y lapiz. herramientas para hacer graficos.',$f21sld${"id": "un-registro-de-bienestar-que-si-quieras-llenar", "area": "salud", "areas2": ["tecnologia"], "titulo": "Un registro de bienestar que sí quieras llenar", "resumen": "Diseña una herramienta sencilla para anotar sueño, ánimo, movimiento o comidas, y prueba qué la hace fácil de usar días tras día.", "tipo": "Prototipo", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Registro de hábitos", "Experiencia de usuario"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Psicología", "Diseño Gráfico", "Medicina", "Educación", "Estadística", "Comunicaciones"], "problema": ["Casi todos hemos descargado una aplicación de hábitos para abandonarla a la semana: demasiados campos, recordatorios molestos o ninguna ganancia visible. Lo que no se registra con constancia no sirve para entender nada.", "Un buen registro debería tardar segundos, mostrarle algo útil a quien lo llena y no pedir más de lo necesario."], "desarrollar": ["Elige dos o tres cosas que alguien quiera observar, como ánimo, sueño y movimiento, y diseña la forma más corta de anotarlas. Haz una maqueta en papel o en una herramienta de diseño, o una hoja de cálculo con formato.", "Pruébala durante una semana contigo o con alguien cercano y anota cuándo se olvidó de llenarla y por qué. El resultado puede ser un prototipo ajustado y una nota sobre qué hizo que funcionara."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara un registro diario con uno semanal para ver cuál se sostiene más."}, {"titulo": "Otro formato", "aporta": "convierte los datos en un gráfico semanal que muestre algo interesante a quien lo llena."}, {"titulo": "Un paso más", "aporta": "piensa cómo cuidar la privacidad si los datos se comparten con alguien."}], "objetivos": ["Definir qué se quiere observar y por qué.", "Diseñar una forma muy corta de registrarlo.", "Probarla durante una semana.", "Ajustarla según lo que resultó incómodo."], "habilidades": ["Diseño centrado en las personas.", "Prototipado.", "Observación de hábitos.", "Presentación de datos."], "herramientas": ["Hoja de cálculo o herramienta de maquetas.", "Papel y lápiz.", "Herramientas para hacer gráficos."], "lineamientos": ["Los registros son personales: no los compartas con datos identificables ni los uses para evaluar a otras personas. Si pruebas la herramienta con alguien, que sea voluntario.", "No interpretes los registros como un diagnóstico de salud mental ni física."], "otroSector": "La misma idea sirve para registrar gastos, estudio, plantas, mantenimientos o tareas del hogar."}$f21sld$::jsonb,21),
('accidentes-comunes-como-prevenirlos-y-que-hacer','salud',array['educacion']::text[],'Accidentes comunes: cómo prevenirlos y qué hacer','Elabora una guía visual sobre los accidentes más comunes del hogar o del estudio, qué los provoca, cómo evitarlos y qué hacer en los primeros minutos.','Guía','~15 h',15,array['Prevención','Primeros auxilios','Seguridad']::text[],array['resolver','crear']::text[],'ficticios',NULL,'enfermeria medicina educacion comunicaciones diseno grafico ingenieria civil ingenieria industrial trabajo social prevencion y gestion de riesgos. busqueda de fuentes oficiales. comunicacion visual. diseno de materiales. herramientas para disenar carteles o tarjetas. documento o presentacion. fuentes oficiales de salud y de defensa civil.',$f22sld${"id": "accidentes-comunes-como-prevenirlos-y-que-hacer", "area": "salud", "areas2": ["educacion"], "titulo": "Accidentes comunes: cómo prevenirlos y qué hacer", "resumen": "Elabora una guía visual sobre los accidentes más comunes del hogar o del estudio, qué los provoca, cómo evitarlos y qué hacer en los primeros minutos.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Prevención", "Primeros auxilios", "Seguridad"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Enfermería", "Medicina", "Educación", "Comunicaciones", "Diseño Gráfico", "Ingeniería Civil", "Ingeniería Industrial", "Trabajo Social"], "problema": ["Caídas, quemaduras, cortes, atragantamientos o golpes ocurren cada día en las casas, los colegios y los lugares de trabajo. La mayoría se podría evitar con pequeños cambios, y muchos empeoran porque nadie sabe qué hacer enseguida.", "Las guías existentes suelen ser largas y técnicas, y se leen justo cuando ya ocurrió el problema."], "desarrollar": ["Elige un lugar, como la cocina de una casa o un laboratorio, y haz una lista de los accidentes más probables. Para cada uno, escribe qué lo provoca, cómo prevenirlo y qué hacer en los primeros minutos hasta que llegue ayuda, tomando la información de fuentes oficiales.", "Preséntalo en un formato que se lea en segundos, como una tarjeta o un cartel con pocos pasos y mucho ícono. Pruébalo con alguien para ver si lo entiende."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la guía para niños, adultos mayores o personas que cuidan a alguien."}, {"titulo": "Una prueba", "aporta": "simula con una persona cercana cómo actuaría con la guía y cuánto tarda en entenderla."}, {"titulo": "Otro formato", "aporta": "conviértela en un recorrido por la casa que muestre dónde están los riesgos."}], "objetivos": ["Identificar los accidentes más comunes de un lugar.", "Explicar cómo prevenirlos.", "Resumir qué hacer en los primeros minutos.", "Probar que la guía se entienda rápido."], "habilidades": ["Prevención y gestión de riesgos.", "Búsqueda de fuentes oficiales.", "Comunicación visual.", "Diseño de materiales."], "herramientas": ["Herramientas para diseñar carteles o tarjetas.", "Documento o presentación.", "Fuentes oficiales de salud y de defensa civil."], "lineamientos": ["La información debe venir de fuentes oficiales, como organismos de salud o cruz roja, y no de memoria. Indica que la guía no reemplaza un curso de primeros auxilios.", "Incluye siempre cuándo llamar a emergencias. No simules heridas reales ni hagas pruebas peligrosas."], "otroSector": "La misma guía puede adaptarse a talleres, laboratorios, obras, parques o transporte escolar."}$f22sld$::jsonb,22),
('actividades-recreativas-saludables-en-tu-comunidad','salud',array['sociedad']::text[],'Actividades recreativas saludables en tu comunidad','Diseña un conjunto de actividades de bajo costo para que un barrio, una escuela o un grupo se muevan, se diviertan y se encuentren.','Plan','~20 h',20,array['Bienestar','Comunidad','Recreación']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social educacion psicologia administracion comunicaciones arquitectura sociologia medicina diseno de programas comunitarios. organizacion de eventos. presupuesto basico. comunicacion y convocatoria. hoja de calculo o calendario. herramientas de diseno para afiches. mapas en linea para ubicar los espacios.',$f23sld${"id": "actividades-recreativas-saludables-en-tu-comunidad", "area": "salud", "areas2": ["sociedad"], "titulo": "Actividades recreativas saludables en tu comunidad", "resumen": "Diseña un conjunto de actividades de bajo costo para que un barrio, una escuela o un grupo se muevan, se diviertan y se encuentren.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Bienestar", "Comunidad", "Recreación"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Trabajo Social", "Educación", "Psicología", "Administración", "Comunicaciones", "Arquitectura", "Sociología", "Medicina"], "problema": ["Muchas comunidades tienen poca oferta recreativa o esta no se adapta a quienes viven ahí: costos altos, horarios que no coinciden o actividades pensadas para otros.", "Una buena actividad recreativa es mucho más que ejercicio: reúne a las personas, reduce el aislamiento y mejora el ánimo. Pero rara vez se diseña con esa mirada."], "desarrollar": ["Elige una comunidad real o inventada, conoce qué espacios tiene y qué intereses hay, y diseña un calendario de cuatro a seis actividades, como caminatas, juegos, talleres o ferias, que se puedan hacer con poco dinero.", "Para cada una indica quién la organiza, qué se necesita y cómo invitar. El resultado puede ser un plan con calendario y materiales, listo para proponerlo a una organización."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta el plan para niños, jóvenes o personas mayores."}, {"titulo": "Otra mirada", "aporta": "calcula un presupuesto mínimo y busca formas de conseguir lo necesario sin gastar."}, {"titulo": "Un paso más", "aporta": "diseña cómo medir si las personas participan y qué las motiva a volver."}], "objetivos": ["Conocer los espacios y los intereses de una comunidad.", "Diseñar actividades realistas y de bajo costo.", "Organizar un calendario con responsables.", "Plantear cómo evaluar la participación."], "habilidades": ["Diseño de programas comunitarios.", "Organización de eventos.", "Presupuesto básico.", "Comunicación y convocatoria."], "herramientas": ["Hoja de cálculo o calendario.", "Herramientas de diseño para afiches.", "Mapas en línea para ubicar los espacios."], "lineamientos": ["Las actividades deben ser seguras e inclusivas para distintas edades y capacidades; si implican esfuerzo físico, aclara que cada persona participa según sus posibilidades.", "No uses imágenes ni datos de personas reales sin su permiso."], "otroSector": "El mismo diseño sirve para actividades culturales, de lectura, de reciclaje o de convivencia vecinal."}$f23sld$::jsonb,23),
('una-campana-para-que-mas-personas-se-hagan-sus-controles-preventivos','salud',array['arte']::text[],'Una campaña para que más personas se hagan sus controles preventivos','Descubre por qué muchas personas no se hacen un control de salud mientras se sienten bien, y diseña una campaña que las invite a hacerlo.','Plan','~25 h',25,array['Campañas','Prevención','Comunicación']::text[],array['crear','resolver']::text[],'ficticios',NULL,'comunicaciones diseno grafico medicina enfermeria psicologia administracion trabajo social educacion comunicacion persuasiva. diseno de campanas. investigacion de publicos. redaccion de mensajes. herramientas de diseno grafico. hoja de calculo. presentacion para exponer el plan.',$f24sld${"id": "una-campana-para-que-mas-personas-se-hagan-sus-controles-preventivos", "area": "salud", "areas2": ["arte"], "titulo": "Una campaña para que más personas se hagan sus controles preventivos", "resumen": "Descubre por qué muchas personas no se hacen un control de salud mientras se sienten bien, y diseña una campaña que las invite a hacerlo.", "tipo": "Plan", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Campañas", "Prevención", "Comunicación"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Comunicaciones", "Diseño Gráfico", "Medicina", "Enfermería", "Psicología", "Administración", "Trabajo Social", "Educación"], "problema": ["Cuando uno se siente bien, nadie quiere perder una mañana en una consulta. Por eso los chequeos preventivos se postergan por falta de tiempo, de información, por costo o por miedo a lo que puedan encontrar.", "Las campañas suelen asustar o recordar un deber, y por eso no convencen. Es más útil entender qué frena a cada grupo y responder a eso."], "desarrollar": ["Elige un grupo de personas y un tipo de control, como el control del niño sano o un chequeo general, y reúne las razones por las que se posterga con datos públicos y conversaciones anónimas. Diseña una campaña con un mensaje central, tres piezas, como afiche, mensaje y video corto, y una forma de hacerla llegar.", "Incluye cómo sabrías si funcionó. El resultado puede ser un plan de campaña con ejemplos de las piezas."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara dos mensajes distintos, uno que informa y otro que emociona, y pruébalos con voluntarios."}, {"titulo": "Un paso más", "aporta": "adapta la campaña para otro grupo que tenga razones distintas."}, {"titulo": "Otro formato", "aporta": "diseña una pieza para quienes no usan redes sociales."}], "objetivos": ["Entender las razones por las que se posterga un control.", "Definir un mensaje y un público.", "Diseñar piezas de campaña.", "Plantear cómo medir su efecto."], "habilidades": ["Comunicación persuasiva.", "Diseño de campañas.", "Investigación de públicos.", "Redacción de mensajes."], "herramientas": ["Herramientas de diseño gráfico.", "Hoja de cálculo.", "Presentación para exponer el plan."], "lineamientos": ["No pidas ni compartas información médica de nadie. Los mensajes deben ser respetuosos: nada de asustar ni culpar.", "No indiques qué controles necesita cada persona: invita a consultar con un servicio de salud."], "otroSector": "La misma campaña sirve para promover el ahorro, la seguridad vial, el voto informado o la revisión de un vehículo."}$f24sld$::jsonb,24),
('higiene-de-manos-en-espacios-compartidos','salud',array['arte']::text[],'Higiene de manos en espacios compartidos','Diseña una propuesta para que más personas se laven las manos en lugares compartidos, como baños, comedores o laboratorios, y descubre qué las hace hacerlo o no.','Plan','~12 h',12,array['Campañas','Prevención','Espacios compartidos']::text[],array['crear','resolver']::text[],'ficticios',NULL,'comunicaciones diseno grafico enfermeria medicina educacion arquitectura ingenieria industrial ingenieria ambiental observacion de espacios. diseno visual. comunicacion persuasiva. evaluacion con indicadores simples. herramientas de diseno grafico. croquis del espacio. hoja de calculo.',$f25sld${"id": "higiene-de-manos-en-espacios-compartidos", "area": "salud", "areas2": ["arte"], "titulo": "Higiene de manos en espacios compartidos", "resumen": "Diseña una propuesta para que más personas se laven las manos en lugares compartidos, como baños, comedores o laboratorios, y descubre qué las hace hacerlo o no.", "tipo": "Plan", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Campañas", "Prevención", "Espacios compartidos"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Comunicaciones", "Diseño Gráfico", "Enfermería", "Medicina", "Educación", "Arquitectura", "Ingeniería Industrial", "Ingeniería Ambiental"], "problema": ["Lavarse las manos es un hábito sencillo y muy útil, pero se olvida o se omite cuando no hay agua, jabón o tiempo, o cuando el lavadero está lejos o sucio. Los carteles de «lávese las manos» rara vez cambian algo.", "En lugares compartidos, el diseño del espacio pesa tanto como el mensaje: dónde está el lavadero, si hay jabón, si se ve y si es cómodo."], "desarrollar": ["Observa, con permiso o con un caso inventado, un espacio compartido y revisa qué facilita o dificulta el lavado de manos. Diseña una propuesta de tres o cuatro cambios: disposición, recordatorios en el lugar y mensajes visuales breves.", "Imagina cómo comprobar que funcionó, por ejemplo con un conteo de uso. El resultado puede ser un plan con bocetos y mensajes, listo para ofrecerlo a una organización."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara mensajes que informan con otros que apelan al humor o a la comunidad."}, {"titulo": "Otro público", "aporta": "adapta la propuesta para niños o para trabajadores que manipulan alimentos."}, {"titulo": "Un paso más", "aporta": "revisa qué recursos, como agua y jabón, hacen falta y cuánto costarían."}], "objetivos": ["Identificar qué facilita o dificulta el hábito en un lugar.", "Diseñar cambios en el espacio y en los mensajes.", "Plantear cómo medir el efecto.", "Presentar la propuesta con claridad."], "habilidades": ["Observación de espacios.", "Diseño visual.", "Comunicación persuasiva.", "Evaluación con indicadores simples."], "herramientas": ["Herramientas de diseño gráfico.", "Croquis del espacio.", "Hoja de cálculo."], "lineamientos": ["No fotografíes a las personas lavándose ni registres su conducta de forma identificable. Pide permiso antes de observar o proponer cambios en un lugar.", "Basa los pasos recomendados de lavado en fuentes oficiales de salud, no en tu criterio."], "otroSector": "La misma propuesta sirve para promover el reciclaje, el ahorro de agua o la limpieza de un espacio común."}$f25sld$::jsonb,25),
('por-que-unas-campanas-de-salud-funcionan-y-otras-no','salud',array['arte']::text[],'¿Por qué unas campañas de salud funcionan y otras no?','Compara campañas de salud pública que lograron cambiar conductas con otras que pasaron desapercibidas, y descubre qué tenían de distinto.','Análisis','~20 h',20,array['Campañas','Comunicación','Análisis de casos']::text[],array['investigar','otro-sector']::text[],'publicos',NULL,'comunicaciones psicologia medicina enfermeria sociologia administracion diseno grafico estadistica analisis de casos. pensamiento critico. comunicacion persuasiva. comparacion sistematica. hoja de calculo para comparar. archivos de campanas de organismos publicos. documento o presentacion.',$f26sld${"id": "por-que-unas-campanas-de-salud-funcionan-y-otras-no", "area": "salud", "areas2": ["arte"], "titulo": "¿Por qué unas campañas de salud funcionan y otras no?", "resumen": "Compara campañas de salud pública que lograron cambiar conductas con otras que pasaron desapercibidas, y descubre qué tenían de distinto.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Campañas", "Comunicación", "Análisis de casos"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Comunicaciones", "Psicología", "Medicina", "Enfermería", "Sociología", "Administración", "Diseño Gráfico", "Estadística"], "problema": ["Algunas campañas de salud se recuerdan años y cambian hábitos; otras se olvidan al día siguiente. Rara vez se analiza con calma qué hizo la diferencia: el mensaje, el medio, el momento, el público o el tono.", "Sin esa mirada, se repiten errores: campañas llenas de datos, con tono de regaño o dirigidas a quien no las ve."], "desarrollar": ["Elige entre cuatro y seis campañas de salud públicas, de tu país o de otros, tres que parezcan haber funcionado y tres que no. Analízalas con una misma lista de criterios: mensaje, emoción, claridad, medio, público y llamado a la acción.", "Busca los patrones que se repiten y escribe una guía breve de lo que parece funcionar. El resultado puede ser un cuadro comparativo y una lista de buenas prácticas."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "investiga qué resultados se midieron y cómo, para distinguir lo que gustó de lo que sirvió."}, {"titulo": "Otro formato", "aporta": "convierte la guía en una lista de verificación para revisar una campaña antes de lanzarla."}, {"titulo": "Un paso más", "aporta": "aplica tus criterios a una campaña nueva que tú propongas."}], "objetivos": ["Seleccionar campañas de salud con resultados distintos.", "Analizarlas con criterios comunes.", "Identificar patrones.", "Escribir buenas prácticas."], "habilidades": ["Análisis de casos.", "Pensamiento crítico.", "Comunicación persuasiva.", "Comparación sistemática."], "herramientas": ["Hoja de cálculo para comparar.", "Archivos de campañas de organismos públicos.", "Documento o presentación."], "lineamientos": ["Usa campañas públicas y cita siempre la fuente. No afirmes que una campaña «funcionó» sin evidencia de sus resultados: distingue lo que gustó de lo que cambió conductas.", "Critica los mensajes y no a las instituciones ni a las personas que aparecen en ellos."], "otroSector": "El mismo análisis sirve para campañas de seguridad vial, de ahorro, de reciclaje o de marketing."}$f26sld$::jsonb,26),
('como-preparar-una-campana-comunitaria-de-prevencion','salud',array['sociedad']::text[],'Cómo preparar una campaña comunitaria de prevención','Construye una guía paso a paso para que un grupo vecinal o estudiantil pueda organizar una campaña de prevención de salud en su comunidad.','Guía','~20 h',20,array['Campañas','Comunidad','Organización']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social administracion comunicaciones educacion psicologia medicina enfermeria sociologia organizacion de proyectos comunitarios. redaccion de guias. planificacion. trabajo con otras personas. documento o presentacion. tablero de tareas o calendario. plantillas de lista de verificacion.',$f27sld${"id": "como-preparar-una-campana-comunitaria-de-prevencion", "area": "salud", "areas2": ["sociedad"], "titulo": "Cómo preparar una campaña comunitaria de prevención", "resumen": "Construye una guía paso a paso para que un grupo vecinal o estudiantil pueda organizar una campaña de prevención de salud en su comunidad.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Campañas", "Comunidad", "Organización"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Trabajo Social", "Administración", "Comunicaciones", "Educación", "Psicología", "Medicina", "Enfermería", "Sociología"], "problema": ["Muchos grupos quieren hacer algo por la salud de su barrio o de su facultad, pero no saben por dónde empezar: qué tema elegir, a quién pedir apoyo, cómo convocar, qué se necesita o cómo saber si sirvió.", "Sin una guía, las campañas terminan siendo un evento aislado, sin continuidad ni evaluación."], "desarrollar": ["Define las etapas de una campaña comunitaria, desde elegir el problema hasta evaluar el resultado, y escribe en cada una preguntas, tareas y ejemplos. Incluye cómo contactar a un servicio de salud local para que respalde la información.", "El resultado puede ser una guía de pocas páginas con listas de verificación y un cronograma de ejemplo, probada con un caso inventado."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la guía para jóvenes, colegios o universidades."}, {"titulo": "Una prueba", "aporta": "pide a un grupo que la use para planificar una campaña ficticia y anota dónde se confundió."}, {"titulo": "Otro formato", "aporta": "conviértela en un tablero de tareas listo para copiar."}], "objetivos": ["Definir las etapas de una campaña.", "Escribir tareas y ejemplos para cada etapa.", "Incluir cómo conseguir apoyo de un servicio de salud.", "Probar que la guía sea fácil de seguir."], "habilidades": ["Organización de proyectos comunitarios.", "Redacción de guías.", "Planificación.", "Trabajo con otras personas."], "herramientas": ["Documento o presentación.", "Tablero de tareas o calendario.", "Plantillas de lista de verificación."], "lineamientos": ["La guía debe indicar que el contenido de salud proviene de un servicio oficial, no de los organizadores. Trabaja con un caso inventado si no hay una campaña real.", "Incluye cómo respetar la privacidad y el consentimiento de las personas que participen."], "otroSector": "La misma guía sirve para campañas de seguridad, reciclaje, limpieza, lectura o convivencia."}$f27sld$::jsonb,27),
('que-informacion-necesita-una-persona-para-decidir-sobre-su-salud','salud',array['arte']::text[],'¿Qué información necesita una persona para decidir sobre su salud?','Descubre qué necesita saber una persona para elegir bien sobre su salud, dónde lo busca y cómo se podría presentar esa información de forma clara y confiable.','Investigación','~20 h',20,array['Información','Comunicación','Decisiones']::text[],array['investigar','resolver']::text[],'publicos',NULL,'comunicaciones psicologia medicina enfermeria educacion diseno grafico ingenieria de sistemas derecho busqueda y evaluacion de fuentes. comunicacion clara. diseno de informacion. pensamiento critico. buscadores y portales de organismos de salud. hoja de calculo para comparar fuentes. herramientas de diseno.',$f28sld${"id": "que-informacion-necesita-una-persona-para-decidir-sobre-su-salud", "area": "salud", "areas2": ["arte"], "titulo": "¿Qué información necesita una persona para decidir sobre su salud?", "resumen": "Descubre qué necesita saber una persona para elegir bien sobre su salud, dónde lo busca y cómo se podría presentar esa información de forma clara y confiable.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Información", "Comunicación", "Decisiones"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Comunicaciones", "Psicología", "Medicina", "Enfermería", "Educación", "Diseño Gráfico", "Ingeniería de Sistemas", "Derecho"], "problema": ["Frente a un síntoma, un tratamiento o un servicio, las personas buscan en internet, preguntan a conocidos o simplemente deciden por intuición. Cada fuente puede ser útil o engañosa, y no siempre se sabe cuál.", "La información oficial suele ser larga, técnica o difícil de encontrar. Cuando falta información clara, la gente se queda con la más fácil, no la más confiable."], "desarrollar": ["Elige una decisión de salud común, como si vale la pena vacunarse, cómo elegir un servicio o qué hacer ante un dolor sin gravedad, y estudia qué información necesita la persona para decidir y dónde la encuentra hoy. Evalúa tres fuentes: su claridad, su confiabilidad y su facilidad de uso.", "Con lo hallado, propón cómo debería ser una buena página o un material que explique esa decisión. El resultado puede ser una maqueta con un ejemplo concreto."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara qué información buscan jóvenes y adultos mayores, y por qué canales."}, {"titulo": "Un paso más", "aporta": "diseña una pequeña lista de preguntas para evaluar si una fuente de salud es confiable."}, {"titulo": "Otro formato", "aporta": "convierte el material en una guía de bolsillo."}], "objetivos": ["Identificar qué información necesita una persona para decidir.", "Evaluar fuentes por claridad y confiabilidad.", "Proponer cómo presentar esa información.", "Elaborar un ejemplo concreto."], "habilidades": ["Búsqueda y evaluación de fuentes.", "Comunicación clara.", "Diseño de información.", "Pensamiento crítico."], "herramientas": ["Buscadores y portales de organismos de salud.", "Hoja de cálculo para comparar fuentes.", "Herramientas de diseño."], "lineamientos": ["No des consejos médicos ni digas qué decisión es correcta: tu trabajo es mejorar cómo se presenta la información. Cita las fuentes oficiales que uses.", "Evita dar ejemplos con casos de salud reales de personas conocidas."], "otroSector": "El mismo análisis sirve para decisiones sobre dinero, trámites, educación o compras importantes."}$f28sld$::jsonb,28),
('vacunas-que-impide-completar-el-esquema-y-como-se-percibe-el-riesgo','salud',array['sociedad']::text[],'Vacunas: ¿qué impide completar el esquema y cómo se percibe el riesgo?','Explora por qué algunas personas o familias no completan sus vacunas, entre horarios, distancia, miedo, desinformación o descuido, y qué podría ayudar.','Investigación','~20 h',20,array['Prevención','Acceso','Comunicación']::text[],array['investigar','resolver']::text[],'publicos',NULL,'medicina enfermeria psicologia trabajo social comunicaciones sociologia estadistica educacion analisis de datos publicos. comunicacion de la salud. comprension del comportamiento. diseno de propuestas. portales de datos de salud publica. hoja de calculo. documento o presentacion.',$f29sld${"id": "vacunas-que-impide-completar-el-esquema-y-como-se-percibe-el-riesgo", "area": "salud", "areas2": ["sociedad"], "titulo": "Vacunas: ¿qué impide completar el esquema y cómo se percibe el riesgo?", "resumen": "Explora por qué algunas personas o familias no completan sus vacunas, entre horarios, distancia, miedo, desinformación o descuido, y qué podría ayudar.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Prevención", "Acceso", "Comunicación"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Medicina", "Enfermería", "Psicología", "Trabajo Social", "Comunicaciones", "Sociología", "Estadística", "Educación"], "problema": ["Una vacuna a medias protege menos, y cada dosis pendiente es una oportunidad perdida. Las razones de que falte una dosis son muy distintas: no hubo tiempo, el servicio quedaba lejos, no se entendió el calendario, hubo miedo o falta de confianza.", "Quienes ven la prevención desde fuera suelen reducir todo a «falta de interés», cuando muchas veces el obstáculo está en cómo se organiza o se explica el servicio."], "desarrollar": ["Reúne información pública sobre cobertura de vacunación y las razones que se mencionan para no completar el esquema. Agrúpalas en barreras prácticas, de información y de confianza.", "Para cada grupo propón una acción realista, como recordatorios, horarios flexibles o mensajes más claros. El resultado puede ser un informe visual con las barreras y una propuesta de qué cambiaría en cada caso."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo percibe el riesgo una persona frente a enfermedades que ya no vemos y por qué eso afecta su decisión."}, {"titulo": "Otro formato", "aporta": "diseña un calendario de vacunación fácil de entender para una familia."}, {"titulo": "Un paso más", "aporta": "analiza cómo se comunica la información en los servicios de salud y qué tan clara es."}], "objetivos": ["Reunir información sobre cobertura de vacunación.", "Agrupar las razones de los esquemas incompletos.", "Proponer acciones para cada tipo de barrera.", "Presentar los hallazgos con claridad y respeto."], "habilidades": ["Análisis de datos públicos.", "Comunicación de la salud.", "Comprensión del comportamiento.", "Diseño de propuestas."], "herramientas": ["Portales de datos de salud pública.", "Hoja de cálculo.", "Documento o presentación."], "lineamientos": ["Trabaja solo con información pública y agregada; no pidas ni muestres carnés de vacunación de nadie. Respeta las distintas opiniones sin burlarte ni atacar a quienes dudan.", "Remite siempre a fuentes oficiales para el calendario y las indicaciones: tú no recomiendas vacunas."], "otroSector": "El mismo análisis sirve para entender por qué se descuidan revisiones periódicas, como el mantenimiento de un vehículo o de un equipo."}$f29sld$::jsonb,29),
('por-que-se-evita-buscar-atencion-aun-cuando-se-necesita','salud',array['sociedad']::text[],'¿Por qué se evita buscar atención aun cuando se necesita?','Descubre qué lleva a una persona a postergar la atención de salud, entre miedo, costo, tiempo, trato o creer que «ya pasará», y qué podría ayudarla a dar el paso.','Investigación','~20 h',20,array['Acceso','Comportamiento','Atención al paciente']::text[],array['investigar','resolver']::text[],'publicos',NULL,'psicologia medicina enfermeria trabajo social sociologia comunicaciones administracion estadistica analisis del comportamiento. mapeo de recorridos. empatia y escucha. redaccion de propuestas. documento o presentacion. hoja de calculo. esquemas de recorrido.',$f30sld${"id": "por-que-se-evita-buscar-atencion-aun-cuando-se-necesita", "area": "salud", "areas2": ["sociedad"], "titulo": "¿Por qué se evita buscar atención aun cuando se necesita?", "resumen": "Descubre qué lleva a una persona a postergar la atención de salud, entre miedo, costo, tiempo, trato o creer que «ya pasará», y qué podría ayudarla a dar el paso.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Acceso", "Comportamiento", "Atención al paciente"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Psicología", "Medicina", "Enfermería", "Trabajo Social", "Sociología", "Comunicaciones", "Administración", "Estadística"], "problema": ["Muchas personas esperan semanas o meses antes de ir a un servicio de salud, y llegan cuando el problema ya es mayor. No es por irresponsabilidad: pesan el costo, el miedo a lo que pueda salir, la mala experiencia anterior o no poder faltar al trabajo.", "Mientras no se entienda esa espera, las campañas que solo dicen «acude a tiempo» no cambian nada."], "desarrollar": ["Con estudios públicos y casos hipotéticos, arma una lista de razones para postergar la atención y ordénalas por frecuencia o por impacto. Construye el recorrido de dos o tres personas inventadas, desde que notan algo hasta que se atienden, y marca los puntos donde dudan.", "Propón qué podría hacer un servicio de salud, una familia o un empleador para facilitar ese paso. El resultado puede ser un esquema de recorridos con propuestas."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara qué razones pesan más en hombres, mujeres, jóvenes y adultos mayores."}, {"titulo": "Otro formato", "aporta": "diseña mensajes breves que respondan a las dudas más comunes."}, {"titulo": "Un paso más", "aporta": "estudia cómo el trato recibido en una primera visita influye en volver o no."}], "objetivos": ["Reunir las razones por las que se posterga la atención.", "Reconstruir recorridos de personas inventadas.", "Identificar los momentos de duda.", "Proponer apoyos concretos."], "habilidades": ["Análisis del comportamiento.", "Mapeo de recorridos.", "Empatía y escucha.", "Redacción de propuestas."], "herramientas": ["Documento o presentación.", "Hoja de cálculo.", "Esquemas de recorrido."], "lineamientos": ["No pidas a nadie que cuente su experiencia de salud; trabaja con estudios públicos y casos inventados. Evita juzgar a quien posterga: describe las razones con respeto.", "No digas qué síntomas requieren atención urgente: remite siempre a un servicio de salud."], "otroSector": "El mismo análisis sirve para entender por qué se posterga un trámite, una revisión del auto o una conversación importante."}$f30sld$::jsonb,30),
('el-camino-de-un-paciente-de-la-posta-al-hospital','salud',array['industria']::text[],'El camino de un paciente: de la posta al hospital','Reconstruye cómo viaja un paciente entre establecimientos de salud cuando lo derivan, y descubre dónde se pierde información, tiempo u orientación.','Análisis','~20 h',20,array['Procesos','Atención al paciente','Referencias']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'ingenieria industrial administracion ingenieria de sistemas medicina enfermeria trabajo social estadistica derecho mapeo de procesos. analisis de flujos de informacion. diseno de servicios. comunicacion visual. diagramas de flujo. hoja de calculo. documento o presentacion.',$f31sld${"id": "el-camino-de-un-paciente-de-la-posta-al-hospital", "area": "salud", "areas2": ["industria"], "titulo": "El camino de un paciente: de la posta al hospital", "resumen": "Reconstruye cómo viaja un paciente entre establecimientos de salud cuando lo derivan, y descubre dónde se pierde información, tiempo u orientación.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Procesos", "Atención al paciente", "Referencias"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Ingeniería Industrial", "Administración", "Ingeniería de Sistemas", "Medicina", "Enfermería", "Trabajo Social", "Estadística", "Derecho"], "problema": ["Cuando un servicio de salud no puede resolver un problema, deriva a la persona a otro, y desde ahí empieza un camino desconocido: ¿adónde ir?, ¿con qué papeles?, ¿quién avisa que va a llegar? Muchas personas se pierden en ese traslado.", "Cada establecimiento conoce su parte, pero nadie ve el recorrido completo. Cuando algo falla, el paciente lo vive como una sucesión de ventanillas sin conexión."], "desarrollar": ["Con un caso inventado, dibuja el recorrido de un paciente desde la primera consulta hasta que lo atienden en otro establecimiento. Marca cada paso: quién decide, qué documento se entrega, cuánto tarda y dónde puede haber confusión.", "Propón mejoras simples, como una hoja clara de derivación, un contacto de seguimiento o información sobre qué esperar. El resultado puede ser un diagrama del recorrido con puntos críticos y una propuesta breve."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara el recorrido en dos contextos distintos, como una ciudad grande y una zona alejada."}, {"titulo": "Un paso más", "aporta": "diseña el material de orientación que recibiría la persona al ser derivada."}, {"titulo": "Otro formato", "aporta": "simula cuánto tiempo se ahorra si se mejora un solo paso del recorrido."}], "objetivos": ["Reconstruir el recorrido de un paciente derivado.", "Identificar los pasos críticos.", "Proponer mejoras de orientación e información.", "Presentarlo con un diagrama claro."], "habilidades": ["Mapeo de procesos.", "Análisis de flujos de información.", "Diseño de servicios.", "Comunicación visual."], "herramientas": ["Diagramas de flujo.", "Hoja de cálculo.", "Documento o presentación."], "lineamientos": ["Trabaja con un caso inventado; no uses historias clínicas ni ejemplos de pacientes reales. Describe los problemas del proceso sin culpar a personas o a establecimientos.", "No indiques cuándo una derivación es necesaria: eso lo decide el equipo de salud."], "otroSector": "El mismo análisis sirve para el recorrido de un trámite entre oficinas, de un pedido entre áreas o de un caso entre juzgados."}$f31sld$::jsonb,31),
('cuando-el-centro-de-salud-se-queda-sin-medicamentos','salud',array['industria']::text[],'Cuando el centro de salud se queda sin medicamentos','Simula cómo se compran, guardan y reparten los medicamentos en un centro de salud con datos inventados, y descubre qué hace que a veces falten y a veces sobren.','Simulación','~30 h',30,array['Logística','Inventarios','Simulación']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'ingenieria industrial administracion ingenieria de sistemas estadistica medicina enfermeria economia contabilidad gestion de inventarios. modelamiento y simulacion basica. analisis de datos. pensamiento sistemico. hoja de calculo. diagramas de flujo. herramientas de simulacion, si se tienen.',$f32sld${"id": "cuando-el-centro-de-salud-se-queda-sin-medicamentos", "area": "salud", "areas2": ["industria"], "titulo": "Cuando el centro de salud se queda sin medicamentos", "resumen": "Simula cómo se compran, guardan y reparten los medicamentos en un centro de salud con datos inventados, y descubre qué hace que a veces falten y a veces sobren.", "tipo": "Simulación", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Logística", "Inventarios", "Simulación"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Ingeniería Industrial", "Administración", "Ingeniería de Sistemas", "Estadística", "Medicina", "Enfermería", "Economía", "Contabilidad"], "problema": ["Cuando falta un medicamento, la persona no puede completar su tratamiento. Cuando sobra, se vence y se desperdicia. Las dos situaciones suelen ocurrir a la vez en el mismo lugar: faltan unos y se pierden otros.", "La razón rara vez es una sola: pedidos mal calculados, entregas que llegan tarde, consumo que cambia por temporada o registros desactualizados."], "desarrollar": ["Arma un modelo sencillo con datos ficticios para tres o cuatro medicamentos: cuánto se consume cada semana, cuánto se pide, cuánto tarda en llegar y cuánto se vence. Simula varias semanas en una hoja de cálculo y observa cuándo se acaba cada uno y cuándo sobra.", "Prueba dos o tres cambios, como pedir antes, pedir más o repartir de otro modo, y compara cuál reduce más las faltas y los vencimientos. El resultado puede ser una pequeña simulación con conclusiones."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "añade una temporada de más enfermedades y observa cómo cambia lo que se necesita."}, {"titulo": "Un paso más", "aporta": "diseña un aviso temprano que alerte cuándo conviene volver a pedir."}, {"titulo": "Otro formato", "aporta": "convierte el modelo en una herramienta que otra persona pueda usar con sus propios datos ficticios."}], "objetivos": ["Describir el ciclo de un medicamento en un centro de salud.", "Construir un modelo simple con datos inventados.", "Simular varias semanas.", "Comparar cambios y explicar cuál funciona mejor."], "habilidades": ["Gestión de inventarios.", "Modelamiento y simulación básica.", "Análisis de datos.", "Pensamiento sistémico."], "herramientas": ["Hoja de cálculo.", "Diagramas de flujo.", "Herramientas de simulación, si se tienen."], "lineamientos": ["Usa solo datos inventados y no nombres reales de establecimientos ni de personas. El modelo es un ejercicio, no una evaluación de ningún centro de salud.", "No indiques cuántos medicamentos necesita un servicio real: eso depende de profesionales de farmacia y de salud."], "otroSector": "El mismo modelo sirve para repuestos de un taller, insumos de un restaurante, útiles de un colegio o productos de una tienda."}$f32sld$::jsonb,32),
('salud-mental-que-dificulta-conseguir-atencion','salud',array['sociedad']::text[],'Salud mental: ¿qué dificulta conseguir atención?','Explora qué barreras encuentra una persona para llegar a una atención de salud mental, como el costo, el estigma, la falta de información o de servicios cercanos, y cómo se podrían reducir.','Investigación','~25 h',25,array['Salud mental','Acceso','Servicios']::text[],array['investigar','resolver']::text[],'publicos',NULL,'psicologia medicina trabajo social sociologia comunicaciones administracion estadistica derecho busqueda de informacion confiable. analisis de barreras de acceso. comunicacion empatica. diseno de guias. documento o presentacion. hoja de calculo. mapas en linea y portales de servicios publicos.',$f33sld${"id": "salud-mental-que-dificulta-conseguir-atencion", "area": "salud", "areas2": ["sociedad"], "titulo": "Salud mental: ¿qué dificulta conseguir atención?", "resumen": "Explora qué barreras encuentra una persona para llegar a una atención de salud mental, como el costo, el estigma, la falta de información o de servicios cercanos, y cómo se podrían reducir.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Salud mental", "Acceso", "Servicios"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Psicología", "Medicina", "Trabajo Social", "Sociología", "Comunicaciones", "Administración", "Estadística", "Derecho"], "problema": ["Muchas personas que podrían beneficiarse de una orientación psicológica no la reciben: no saben a dónde ir, no pueden pagarla, hay pocos profesionales cerca o temen que las juzguen. El tema todavía se vive con silencio.", "Sin entender esas barreras, las campañas dicen «busca ayuda» pero no indican cómo ni dónde, ni se ocupan de lo que lo vuelve difícil."], "desarrollar": ["Reúne información pública sobre los servicios de salud mental disponibles y las barreras que se señalan en estudios o informes. Arma un cuadro de las barreras por tipo: de información, de costo, de distancia, de confianza y de tiempo.", "Con eso, diseña una guía breve de cómo orientarse y una propuesta de qué mejorarían los servicios. El resultado puede ser una guía de recursos con un análisis de barreras."], "ampliaciones": [{"titulo": "Otro público", "aporta": "repite el análisis para estudiantes universitarios, adolescentes o personas que trabajan."}, {"titulo": "Otra mirada", "aporta": "estudia cómo cambia el acceso con la atención en línea y sus limitaciones."}, {"titulo": "Un paso más", "aporta": "diseña un mapa de servicios orientativo de una localidad con datos públicos."}], "objetivos": ["Reunir información sobre servicios de salud mental.", "Identificar las barreras para acceder.", "Elaborar una guía de orientación.", "Proponer mejoras de los servicios."], "habilidades": ["Búsqueda de información confiable.", "Análisis de barreras de acceso.", "Comunicación empática.", "Diseño de guías."], "herramientas": ["Documento o presentación.", "Hoja de cálculo.", "Mapas en línea y portales de servicios públicos."], "lineamientos": ["Es un tema delicado: no pidas relatos personales ni hagas pruebas ni diagnósticos. Usa datos públicos y no compartas información sobre personas concretas.", "La guía debe incluir siempre a dónde acudir en una crisis, con los números oficiales de tu país, y aclarar que no reemplaza la atención de un profesional."], "otroSector": "El mismo análisis sirve para el acceso a la justicia, a la asesoría legal o a la educación especial."}$f33sld$::jsonb,33),
('esta-tu-salon-o-tu-oficina-lista-para-una-emergencia-de-salud','salud',array['ciudades']::text[],'¿Está tu salón o tu oficina lista para una emergencia de salud?','Revisa cuánto está preparado un lugar de estudio o de trabajo para atender a alguien que se desmaya, se atraganta o se lesiona, y propone qué le falta.','Análisis','~15 h',15,array['Prevención','Gestión de riesgos','Primeros auxilios']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria industrial ingenieria civil enfermeria medicina administracion educacion arquitectura ingenieria ambiental evaluacion de riesgos. elaboracion de listas de verificacion. planificacion. comunicacion clara. hoja de calculo o formulario. croquis del lugar. herramientas para disenar carteles.',$f34sld${"id": "esta-tu-salon-o-tu-oficina-lista-para-una-emergencia-de-salud", "area": "salud", "areas2": ["ciudades"], "titulo": "¿Está tu salón o tu oficina lista para una emergencia de salud?", "resumen": "Revisa cuánto está preparado un lugar de estudio o de trabajo para atender a alguien que se desmaya, se atraganta o se lesiona, y propone qué le falta.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Prevención", "Gestión de riesgos", "Primeros auxilios"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Ingeniería Industrial", "Ingeniería Civil", "Enfermería", "Medicina", "Administración", "Educación", "Arquitectura", "Ingeniería Ambiental"], "problema": ["Casi todos pasamos horas en lugares donde, si alguien se siente mal, nadie sabe bien qué hacer: no hay botiquín visible, no se sabe quién llama a emergencias ni a dónde llevar a la persona.", "Los planes de emergencia suelen pensarse para sismos o incendios y dejan de lado lo más probable: un desmayo, una caída o una crisis de salud de una persona."], "desarrollar": ["Con permiso, revisa un lugar que conozcas y evalúa con una lista de verificación: botiquín, teléfonos de emergencia visibles, personas con capacitación, rutas de acceso y quién decide qué hacer. Anota qué hay y qué falta.", "Propón cinco mejoras de bajo costo y un pequeño protocolo de tres pasos. El resultado puede ser un informe breve con la lista de verificación y un cartel con el protocolo."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "repite la revisión en dos lugares distintos y compara qué diferencias importan."}, {"titulo": "Una prueba", "aporta": "haz un simulacro sencillo con voluntarios y mide cuánto tardaron en reaccionar."}, {"titulo": "Un paso más", "aporta": "organiza una breve charla de orientación y evalúa cuánto se aprendió."}], "objetivos": ["Evaluar si un lugar está preparado para una emergencia de salud.", "Detectar lo que falta.", "Proponer mejoras de bajo costo.", "Elaborar un protocolo simple."], "habilidades": ["Evaluación de riesgos.", "Elaboración de listas de verificación.", "Planificación.", "Comunicación clara."], "herramientas": ["Hoja de cálculo o formulario.", "Croquis del lugar.", "Herramientas para diseñar carteles."], "lineamientos": ["Pide permiso antes de revisar un lugar. No simules emergencias reales ni hagas pruebas con personas que tengan alguna condición de salud.", "El protocolo debe indicar llamar siempre a emergencias; los pasos de ayuda deben provenir de fuentes oficiales, no de tu criterio."], "otroSector": "El mismo análisis sirve para evaluar la preparación ante sismos, incendios, cortes de luz o fallas de seguridad."}$f34sld$::jsonb,34),
('como-proteger-tu-informacion-personal-durante-una-atencion-de-salud','salud',array['derecho']::text[],'¿Cómo proteger tu información personal durante una atención de salud?','Descubre qué información se pide en una atención de salud, quién puede verla y qué derechos tiene la persona, y conviértelo en una guía fácil de seguir.','Guía','~12 h',12,array['Privacidad','Derechos del paciente']::text[],array['resolver','crear']::text[],'ficticios',NULL,'derecho ingenieria de sistemas ingenieria de software medicina enfermeria administracion comunicaciones psicologia lectura de normativa. privacidad de datos. redaccion en lenguaje simple. diseno de guias. documento o presentacion. portales de normativa y de la autoridad de proteccion de datos. herramientas de diseno.',$f35sld${"id": "como-proteger-tu-informacion-personal-durante-una-atencion-de-salud", "area": "salud", "areas2": ["derecho"], "titulo": "¿Cómo proteger tu información personal durante una atención de salud?", "resumen": "Descubre qué información se pide en una atención de salud, quién puede verla y qué derechos tiene la persona, y conviértelo en una guía fácil de seguir.", "tipo": "Guía", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Privacidad", "Derechos del paciente"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Ingeniería de Software", "Medicina", "Enfermería", "Administración", "Comunicaciones", "Psicología"], "problema": ["En un centro de salud se da el nombre, el documento, el teléfono, los síntomas y los antecedentes, muchas veces en voz alta frente a otras personas o en formularios que nadie sabe a dónde van. La información de salud es de las más sensibles que existe.", "Pocas personas saben qué pueden pedir, qué pueden negarse a dar o cómo quejarse si su información se usa mal."], "desarrollar": ["Revisa la normativa pública sobre protección de datos personales y derechos de los pacientes de tu país, y traduce lo esencial a lenguaje simple. Haz una lista de situaciones comunes: llenar un formulario, dar el teléfono, enviar resultados por mensaje, y explica en cada una qué es prudente.", "El resultado puede ser una guía de una o dos páginas con ejemplos y a quién acudir en caso de duda."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la guía para padres que llevan a sus hijos o para personas mayores."}, {"titulo": "Otra mirada", "aporta": "revisa un formulario inventado de un servicio y marca qué datos pide de más."}, {"titulo": "Otro formato", "aporta": "convierte la guía en una tarjeta con tres preguntas para hacer antes de dar información."}], "objetivos": ["Identificar qué información personal se pide en una atención.", "Explicar los derechos de los pacientes en lenguaje simple.", "Describir situaciones comunes y cómo actuar.", "Elaborar una guía clara."], "habilidades": ["Lectura de normativa.", "Privacidad de datos.", "Redacción en lenguaje simple.", "Diseño de guías."], "herramientas": ["Documento o presentación.", "Portales de normativa y de la autoridad de protección de datos.", "Herramientas de diseño."], "lineamientos": ["La guía es informativa y no asesoría legal: cita las normas que uses e indica dónde consultar. No uses datos reales de nadie en los ejemplos.", "No afirmes lo que se puede o no hacer sin respaldo de una fuente oficial."], "otroSector": "La misma guía sirve para proteger datos en bancos, tiendas en línea, colegios o aplicaciones."}$f35sld$::jsonb,35)
